import{createFrog,padAt,landingAt,findPad,pressRear,releaseRear,hand,advance,cancelControls}from'./core.mjs';
const $=id=>document.getElementById(id),canvas=$('pond'),ctx=canvas.getContext('2d');let s=createFrog(),best=0,last=performance.now(),camera=0,visual=0,shared=false;
try{best=Number(localStorage.getItem('hop-off-best-v1'))||0}catch{}$('best').textContent=`${Math.floor(best)} m`;
function begin(){s=createFrog();s.status='playing';camera=0;last=performance.now();$('overlay').hidden=true;$('share').hidden=true;shared=false;syncControls();}
function finish(){if(s.z>best){best=s.z;try{localStorage.setItem('hop-off-best-v1',String(best))}catch{}}$('best').textContent=`${Math.floor(best)} m`;$('overlay-label').textContent='CERTIFIED POND GOBLIN';$('overlay-title').textContent=`${Math.floor(s.z)} meters. Splash.`;$('overlay-copy').textContent=`${s.hops} clean ${s.hops===1?'hop':'hops'}. ${s.hops<1?'Aim the green ring at the first pad. Hold both feet for about half a second.':'A little more aim. A little less ambition.'}`;$('start').textContent='ONE MORE HOP →';$('share').hidden=false;$('overlay').hidden=false;syncControls();}
function pause(){if(s.status!=='playing')return;s.status='paused';cancelControls(s);syncControls();$('overlay-label').textContent='POND BREAK';$('overlay-title').textContent='Just floating.';$('overlay-copy').textContent='Your frog is exactly where you left it.';$('start').textContent='KEEP HOPPING →';$('share').hidden=true;$('overlay').hidden=false;}
$('start').onclick=()=>{if(s.status==='paused'){s.status='playing';last=performance.now();$('overlay').hidden=true}else begin()};$('restart').onclick=begin;$('pause').onclick=pause;$('help').onclick=()=>{pause();$('help-dialog').showModal()};$('close-help').onclick=()=>{ $('help-dialog').close()};$('got-it').onclick=()=>{$('help-dialog').close()};
const rearButtons=[...document.querySelectorAll('[data-rear]')],handButtons=[...document.querySelectorAll('[data-hand]')];
function syncControls(){rearButtons.forEach((b,i)=>{b.classList.toggle('active',s.rear[i]);b.setAttribute('aria-pressed',String(s.rear[i]))});handButtons.forEach((b,i)=>{b.classList.toggle('active',s.hands[i]);b.setAttribute('aria-pressed',String(s.hands[i]))});}
const pointers=new Map();
function wire(button,i,isRear){button.addEventListener('pointerdown',e=>{if(e.button!==0||s.status!=='playing')return;e.preventDefault();button.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{i,isRear});if(isRear)pressRear(s,i);else hand(s,i,true);syncControls()});const release=e=>{const p=pointers.get(e.pointerId);if(!p)return;pointers.delete(e.pointerId);if(p.isRear)releaseRear(s,p.i);else hand(s,p.i,false);syncControls()};button.addEventListener('pointerup',release);button.addEventListener('lostpointercapture',release);button.addEventListener('pointercancel',e=>{if(!pointers.has(e.pointerId))return;pointers.delete(e.pointerId);cancelControls(s);syncControls()});button.addEventListener('keydown',e=>{if((e.key===' '||e.key==='Enter')&&!e.repeat){e.preventDefault();if(isRear)pressRear(s,i);else hand(s,i,true);syncControls()}});button.addEventListener('keyup',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();if(isRear)releaseRear(s,i);else hand(s,i,false);syncControls()}});}
rearButtons.forEach((b,i)=>wire(b,i,true));handButtons.forEach((b,i)=>wire(b,i,false));
const heldKeys=new Set();addEventListener('keydown',e=>{if($('help-dialog').open||e.altKey||e.ctrlKey||e.metaKey)return;if(e.key==='Escape'){pause();return}if(e.target.closest('button')&&(e.key===' '||e.key==='Enter'))return;const k=e.key.toLowerCase();if(!['a','d','j','k',' ','arrowleft','arrowright'].includes(k))return;e.preventDefault();if(e.repeat||heldKeys.has(k))return;heldKeys.add(k);if(k==='a'||k==='arrowleft')hand(s,0,true);if(k==='d'||k==='arrowright')hand(s,1,true);if(k==='j'||k===' ')pressRear(s,0);if(k==='k'||k===' ')pressRear(s,1);syncControls()});addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(!heldKeys.delete(k))return;if(k==='a'||k==='arrowleft')hand(s,0,false);if(k==='d'||k==='arrowright')hand(s,1,false);if(k==='j'||k===' ')releaseRear(s,0);if(k==='k'||k===' ')releaseRear(s,1);syncControls()});
addEventListener('blur',()=>{heldKeys.clear();pointers.clear();pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){heldKeys.clear();pointers.clear();pause()}});
$('share').onclick=async()=>{const text=`My frog made it ${Math.floor(s.z)}m before becoming pond soup. Beat that. 🐸`,url=new URL('/frog/',location.href).href;try{if(navigator.share)await navigator.share({title:'HOP OFF!',text,url});else{await navigator.clipboard.writeText(`${text} ${url}`);$('share').textContent='Challenge link copied ✓'}}catch{ $('share').textContent='Share this page with a friend ↗'}};
function ellipse(x,y,rx,ry,fill,stroke,width=2){ctx.beginPath();ctx.ellipse(x,y,Math.max(.1,rx),Math.max(.1,ry),0,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke()}}
function line(points,color,width){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke()}
function frog(x,y,scale,jump){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);const charge=s.charges[0]+s.charges[1],squat=charge*3;ctx.translate(0,squat);const outline='#164c45';
// Rear feet load independently. Airborne feet extend behind the frog.
for(let i=0;i<2;i++){const side=i===0?-1:1,c=s.charges[i],reach=jump?22:0;line([[side*23,11],[side*(42-c*10),26],[side*(31+reach),43-c*12]],outline,14);line([[side*23,11],[side*(42-c*10),26],[side*(31+reach),43-c*12]],i===0?'#d5ff6f':'#7aecd9',9);ellipse(side*(31+reach),43-c*12,13,6,i===0?'#d5ff6f':'#7aecd9',outline,2)}
ellipse(0,5,35,39,'#91d859',outline,3);ellipse(0,19,23,22,'#d4ed9a');
for(let i=0;i<2;i++){const side=i===0?-1:1,out=s.hands[i]?19:0;line([[side*25,-4],[side*(41+out),7-out*.6],[side*(39+out),22-out*.7]],outline,11);line([[side*25,-4],[side*(41+out),7-out*.6],[side*(39+out),22-out*.7]],i===0?'#bda2ff':'#ff9aca',7);ellipse(side*(39+out),22-out*.7,8,4,i===0?'#bda2ff':'#ff9aca',outline,2)}
ellipse(0,-15,37,28,'#b7ed70',outline,3);for(const side of[-1,1]){ellipse(side*23,-35,15,19,'#b7ed70',outline,3);ellipse(side*23,-39,9,11,'#fffbe7');ellipse(side*23,-42,4,6,'#163d3b');ellipse(side*25,-45,1.7,2,'#fff')}
line([[0,-4],[0,22]],'#64af54',3);ellipse(-12,3,4,6,'#74bd55');ellipse(13,10,4,6,'#74bd55');ctx.restore()}
function draw(dt){const w=canvas.clientWidth,h=canvas.clientHeight,dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);visual+=dt;camera+=(s.z-camera)*(1-Math.exp(-8*dt));const horizon=h*.20,floor=h*.97;const project=(x,z)=>{const d=z-camera+2,scale=1/(1+Math.max(-.8,d)*.14);return{x:w/2+(x-s.x*.15)*w*.23*scale,y:horizon+(floor-horizon)*scale,scale,d}};
const bg=ctx.createLinearGradient(0,0,0,h);bg.addColorStop(0,'#1a2347');bg.addColorStop(.2,'#24595d');bg.addColorStop(1,'#102f46');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);
ellipse(w*.70,h*.12,18,18,'#daffb8');ellipse(w*.71,h*.115,18,18,'#233f55');
// Perspective banks frame a trail receding toward the horizon.
for(const side of[-1,1]){const edge=Array.from({length:40},(_,i)=>{const p=project(side*(2.5+Math.sin((camera+i*2)*.07)*.2),camera+i*2-2);return[p.x,p.y]});ctx.beginPath();ctx.moveTo(side<0?0:w,h);edge.forEach(([x,y])=>ctx.lineTo(x,y));ctx.lineTo(side<0?0:w,horizon);ctx.closePath();ctx.fillStyle=side<0?'#194a4c':'#1a514e';ctx.fill();line(edge,'#3c8775',2);}
for(let i=0;i<25;i++){const z=Math.floor(camera/4)*4+i*4;const p=project(Math.sin(i*5.1)*2.1,z);line([[p.x-12*p.scale,p.y],[p.x+12*p.scale,p.y]],'#6cc5bf22',1);}
for(let i=s.pad+9;i>=Math.max(0,s.pad-2);i--){const p=padAt(i),v=project(p.x,p.z);if(v.d<-.8)continue;const rx=w*.23*p.halfWidth*v.scale,ry=h*.105*p.halfDepth*v.scale*v.scale;ellipse(v.x,v.y+5*v.scale,rx,ry,'#081f3099');ellipse(v.x,v.y,rx,ry,i===s.pad?'#96ce60':i===s.pad+1?'#7abd65':'#4a9a70','#a7e57c77',Math.max(1,2*v.scale));line([[v.x,v.y],[v.x+rx*.78,v.y-ry*.54]],'#37785f',Math.max(1,2*v.scale));if(i===s.pad+1){ctx.fillStyle='#d9f8be';ctx.font=`bold ${Math.max(9,13*v.scale)}px Arial`;ctx.textAlign='center';ctx.fillText('NEXT',v.x,v.y-3*v.scale);}}
if(s.status==='playing'&&!s.flight&&(s.charges[0]+s.charges[1]>.03)){const aim=landingAt(s),v=project(aim.x,aim.z),good=!!findPad(aim.x,aim.z,s.pad);ctx.beginPath();ctx.ellipse(v.x,v.y,w*.08*v.scale,h*.026*v.scale,0,0,Math.PI*2);ctx.strokeStyle=good?'#d5ff6f':'#ff9aca';ctx.lineWidth=3;ctx.setLineDash([5,4]);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=good?'#d5ff6f':'#ffb1d8';ctx.font='bold 8px Arial';ctx.textAlign='center';ctx.fillText(good?'LAND HERE ✓':'LANDING',v.x,v.y-12);}
const v=project(s.x,s.z),t=s.flight?Math.min(1,s.flight.elapsed/s.flight.duration):0,jump=Math.sin(t*Math.PI),lift=jump*h*.20;ellipse(v.x,v.y+7,34*v.scale*(1-jump*.25),9*v.scale,'#061c30aa');if(s.status==='over'){for(let i=0;i<3;i++)ellipse(v.x,v.y,20+i*15+Math.sin(visual*3)*3,4+i*5,'#00000000','#8de9dc55',2);frog(v.x,v.y+18,v.scale*.64,0)}else frog(v.x,v.y-31*v.scale-lift,v.scale*.72,jump);
// Foreground reeds and fireflies stay outside the playable path.
for(let i=0;i<7;i++){const side=i%2?1:-1,x=w/2+side*w*(.43+(i%3)*.025),y=h*(.43+(i%4)*.17);line([[x,y+19],[x+side*4,y-7],[x+side*13,y-14]],'#59a888',2);ellipse(w*(.12+((i*.239)% .8)),h*(.17+((i*.137)%.55))+Math.sin(visual+i)*4,1.5,1.5,'#d5ff6f99');}}
function frame(now){const dt=Math.min(.04,Math.max(0,(now-last)/1000));last=now;const was=s.status;advance(s,dt);if(was==='playing'&&s.status==='over')finish();$('distance').innerHTML=`${Math.floor(s.z)}<span>m</span>`;$('hops').textContent=`${s.hops} clean ${s.hops===1?'hop':'hops'}`;$('power-left').value=s.charges[0];$('power-right').value=s.charges[1];const aim=landingAt(s),good=!!findPad(aim.x,aim.z,s.pad);$('aim-label').textContent=s.flight?'AIRBORNE. STEER WITH YOUR HANDS.':s.charges.some(c=>c>.03)?good?'ON TARGET · RELEASE TO HOP':`RANGE ${Math.round(aim.z-s.z)}m · ${aim.z<padAt(s.pad+1).z?'KEEP LOADING':'CHECK YOUR AIM'}`:'HOLD REAR FEET TO LOAD';$('aim-label').style.color=good?'#d5ff6f':'#b9accf';$('feedback').textContent=s.message;draw(dt);requestAnimationFrame(frame)}requestAnimationFrame(frame);
